// Some portions generated by Codex

// @ts-check
const fs = require('node:fs');
const { test, expect } = require('@playwright/test');

const WORKBENCH_BASE_URL = (process.env.RDF4J_WORKBENCH_BASE_URL ||
    'http://localhost:8080/rdf4j-workbench').replace(/\/+$/, '');
const SERVER_BASE_URL = (process.env.RDF4J_SERVER_BASE_URL ||
    WORKBENCH_BASE_URL.replace(/\/rdf4j-workbench$/, '/rdf4j-server')).replace(/\/+$/, '');
const THEME_KEY = 'rdf4j-workbench-theme';
const EVIDENCE_DIR = process.env.WORKBENCH_THEME_FIRST_PAINT_EVIDENCE_DIR ||
    '/tmp/rdf4j7-workbench-dark-flash-20260930/first-paint';
const FIRST_PAINT_CASES = [
    {
        name: 'stored dark preference with light system setting on query route',
        path: repositoryId => `/repositories/${repositoryId}/query`,
        repository: true,
        preference: 'dark',
        system: 'light',
        expectedCanvas: '#080e11',
        expectedBackground: 'rgb(8, 14, 17)',
        gate: 'model',
        screenshot: true
    },
    {
        name: 'stored light preference with dark system setting on repository list',
        path: () => '/repositories',
        repository: false,
        preference: 'light',
        system: 'dark',
        expectedCanvas: '#f5f9fb',
        expectedBackground: 'rgb(245, 249, 251)',
        gate: 'application',
        screenshot: false
    },
    {
        name: 'stored dark preference before first stylesheet with light system setting',
        path: () => '/repositories',
        repository: false,
        preference: 'dark',
        system: 'light',
        gate: 'stylesheet',
        screenshot: false
    }
];

function memoryRepositoryConfig(repositoryId) {
    return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ; config:rep.id "${repositoryId}" ; rdfs:label "Workbench theme first-paint fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ] ].`;
}

for (const scenario of FIRST_PAINT_CASES) {
    test(`first Workbench frame honors ${scenario.name}`, async ({ page, request }) => {
        const repositoryId = scenario.repository
            ? `theme-first-paint-${process.pid}-${Date.now()}` : null;
        const repositoryUrl = repositoryId ? `${SERVER_BASE_URL}/repositories/${repositoryId}` : null;
        const routePath = scenario.path(repositoryId);
        const targetUrl = WORKBENCH_BASE_URL + routePath;
        const expectedPath = new URL(targetUrl).pathname.replace(/\/+$/, '');
        let themeScriptRequests = 0;
        page.on('request', request => {
            if (new URL(request.url()).pathname.endsWith('/scripts/workbench-theme.js')) {
                themeScriptRequests++;
            }
        });
        await page.emulateMedia({ colorScheme: scenario.system });
        await page.addInitScript(({ key, preference }) => {
            window.localStorage.setItem(key, preference);
            window.__workbenchThemeFirstFrame = null;
            window.__workbenchThemePaints = [];

            const readTheme = () => {
                const root = document.documentElement;
                const body = document.body;
                const rootStyle = getComputedStyle(root);
                const colorSchemeMeta = document.querySelector('meta[name="color-scheme"]');
                return {
                    theme: root.getAttribute('data-theme'),
                    colorScheme: rootStyle.colorScheme,
                    colorSchemeMeta: colorSchemeMeta ? colorSchemeMeta.content : null,
                    canvas: rootStyle.getPropertyValue('--workbench-canvas').trim(),
                    rootBackground: rootStyle.backgroundColor,
                    bodyBackground: body ? getComputedStyle(body).backgroundColor : null,
                    readyState: document.readyState
                };
            };
            window.__readWorkbenchThemeFrame = readTheme;

            const captureFirstStyledFrame = () => {
                const stylesheetLinks = Array.from(document.querySelectorAll('link[rel="stylesheet"]'));
                const allStylesheetsLoaded = stylesheetLinks.length > 0 &&
                    stylesheetLinks.every(link => link.sheet !== null);
                if (!window.__workbenchThemeFirstFrame && allStylesheetsLoaded && document.body) {
                    window.__workbenchThemeFirstFrame = readTheme();
                }
                if (!window.__workbenchThemeFirstFrame) {
                    requestAnimationFrame(captureFirstStyledFrame);
                }
            };

            requestAnimationFrame(captureFirstStyledFrame);
            if (typeof PerformanceObserver === 'function') {
                try {
                    new PerformanceObserver((list) => {
                        for (const entry of list.getEntries()) {
                            if (entry.entryType === 'paint') {
                                window.__workbenchThemePaints.push({
                                    name: entry.name,
                                    startTime: entry.startTime,
                                    theme: readTheme()
                                });
                            }
                        }
                    }).observe({ type: 'paint', buffered: true });
                } catch (error) {
                    window.__workbenchThemePaintObserverError = String(error);
                }
            }
        }, { key: THEME_KEY, preference: scenario.preference });

        let releaseGate;
        const gate = new Promise((resolve) => { releaseGate = resolve; });
        let gateSeen;
        const gateRequestSeen = new Promise((resolve) => { gateSeen = resolve; });
        const evidenceName = scenario.gate === 'stylesheet' ? 'dark-css-pending'
            : scenario.preference + (scenario.repository ? '-query' : '-repositories');
        fs.mkdirSync(EVIDENCE_DIR, { recursive: true });
        let released = false;
        const release = () => {
            if (!released) {
                released = true;
                releaseGate();
            }
        };
        try {
            if (repositoryUrl) {
                const created = await request.put(repositoryUrl, {
                    headers: { 'Content-Type': 'text/turtle' },
                    data: memoryRepositoryConfig(repositoryId)
                });
                expect([200, 201, 204]).toContain(created.status());
            }

            await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
            themeScriptRequests = 0;
            await page.route('**/*', async (route) => {
                const browserRequest = route.request();
                const requestUrl = new URL(browserRequest.url());
                const accept = browserRequest.headers().accept || '';
                const shouldGateModel = scenario.gate === 'model' && browserRequest.method() === 'GET' &&
                    requestUrl.pathname.replace(/\/+$/, '') === expectedPath &&
                    accept.includes('application/vnd.rdf4j.workbench+ndjson');
                const shouldGateApplication = scenario.gate === 'application' && browserRequest.method() === 'GET' &&
                    requestUrl.pathname.endsWith('/scripts/workbenchApp.js');
                const shouldGateStylesheet = scenario.gate === 'stylesheet' && browserRequest.method() === 'GET' &&
                    requestUrl.pathname.endsWith('/styles/default/screen.css');
                if (shouldGateModel || shouldGateApplication || shouldGateStylesheet) {
                    gateSeen({ url: browserRequest.url(), accept });
                    await gate;
                }
                await route.continue();
            });

            const waitUntil = scenario.gate === 'model' ? 'domcontentloaded' : 'commit';
            await page.reload({ waitUntil });
            const gateRequest = await gateRequestSeen;
            let firstFrame;
            if (scenario.gate === 'stylesheet') {
                firstFrame = await page.evaluate(() => ({
                    ...window.__readWorkbenchThemeFrame(),
                    paints: performance.getEntriesByType('paint').map(entry => ({
                        name: entry.name,
                        startTime: entry.startTime
                    })),
                    title: document.title,
                    href: location.href,
                    viewport: { width: innerWidth, height: innerHeight }
                }));
            } else {
                await page.waitForFunction(() => Boolean(window.__workbenchThemeFirstFrame));
                firstFrame = await page.evaluate(() => ({
                    ...window.__workbenchThemeFirstFrame,
                    paints: window.__workbenchThemePaints,
                    title: document.title,
                    href: location.href,
                    viewport: { width: innerWidth, height: innerHeight }
                }));
            }
            fs.writeFileSync(`${EVIDENCE_DIR}/${evidenceName}.json`, JSON.stringify({
                scenario,
                gateRequest,
                firstFrame
            }, null, 2) + '\n');
            if (scenario.screenshot) {
                await page.screenshot({
                    path: `${EVIDENCE_DIR}/${evidenceName}.png`,
                    fullPage: scenario.gate !== 'stylesheet',
                    timeout: 5000
                });
            }

            if (scenario.gate === 'stylesheet') {
                expect(firstFrame.theme, 'root theme before the first stylesheet response').toBe(scenario.preference);
                expect(firstFrame.colorSchemeMeta, 'resolved color scheme before the first stylesheet response')
                    .toBe(scenario.preference);
            } else {
                expect(firstFrame.canvas, 'canvas token during the first styled frame').toBe(scenario.expectedCanvas);
                expect(firstFrame.colorScheme, 'computed color scheme during the first styled frame')
                    .toBe(scenario.preference);
                expect(firstFrame.rootBackground, 'root canvas during the first styled frame')
                    .toBe(scenario.expectedBackground);
                expect(firstFrame.bodyBackground, 'body canvas during the first styled frame')
                    .toBe(scenario.expectedBackground);
            }

            release();
            await page.locator('#workbench-page-surface').waitFor({ state: 'attached' });
            await page.waitForFunction((preference) =>
                window.RDF4JWorkbenchTheme && document.documentElement.getAttribute('data-theme') === preference,
                scenario.preference);
            await expect(page.locator('script[src$="/scripts/workbench-theme.js"]')).toHaveCount(1);
            expect(themeScriptRequests, 'the early theme resolver is fetched once per document').toBe(1);
        } finally {
            release();
            if (repositoryUrl) {
                const removed = await request.delete(repositoryUrl);
                expect([200, 204, 404]).toContain(removed.status());
            }
        }
    });
}
